        Exercise(id: UUID(uuidString: "A36D447B-DBB4-5E66-0313-913F958A5473")!, name: "90/90 Hip Stretch", muscle: .mobility, category: "bodyweight", instructions: "Sit with both legs at 90 degrees. Switch sides, opening hip internal/external rotation."),
        Exercise(id: UUID(uuidString: "6EA69D95-AE5F-D4ED-19B4-03F698B0209E")!, name: "Shoulder Dislocates", muscle: .mobility, category: "bodyweight", instructions: "Hold band or stick wide. Pass overhead behind back and return. Shoulder mobility."),
    ]
